e","options":["Yes","No","Not sure","Prefer not to answer"],"showWhen":null,"provenance":"assumed"},{"id":"bleeding_details","section":"symptoms","label":"Describe the blood, amount, frequency and whether mixed with stool or on its surface.","kind":"text","options":[],"showWhen":{"id":"rectal_blood","is":"Yes"},"provenance":"assumed"},{"id":"fatigue","section":"symptoms","label":"Unusual tiredness or breathlessness with usual activity?","kind":"choice","options":["Yes","No","Not sure","Prefer not to answer"],"showWhen":null,"provenance":"assumed"},{"id":"medicines","section":"history","label":"Current/recent medicines, painkillers, blood thinners, acidity tablets and herbal/home remedies; include duration.","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"allergies","section":"history","label":"Medicine or food allergies and reactions (write 'none known' only if confirmed).","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"conditions","section":"history","label":"Known illnesses and when diagnosed, including diabetes, liver disease, ulcers or gallstones.","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"surgery","section":"history","label":"Previous operations, hospital admissions or endoscopy, with approximate dates.","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"family","section":"history","label":"Family history of cancer or bowel polyps: relative, organ and age if known.","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"tobacco","section":"history","label":"Tobacco, betel/areca or alcohol use: type, amount and duration; none only if confirmed.","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"tb_history","section":"history","label":"Past tuberculosis, close contact, prolonged fever or night sweats? Give details or say not known.","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"first_symptom_date","section":"history","label":"Approximate date symptoms first started.","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"first_contact","section":"history","label":"Who was first consulted?","kind":"choice","options":["Nobody yet","Pharmacist","General physician","GI specialist","Other practitioner","Not sure"],"showWhen":null,"provenance":"assumed"},{"id":"previous_treatment","section":"history","label":"When was the first consultation? What was the problem treated as, what was tried, and did it help?","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"visits","section":"history","label":"How many consultations before this visit, and who referred the patient?","kind":"text","options":[],"showWhen":null,"provenance":"assumed"},{"id":"previous_tests","section":"history","label":"Previous tests and dates, even if reports are not available.","kind":"text","options":[],"showWhen":null,"provenance":"assumed"}],"rules":[{"id":"active_bleeding","urgency":"immediate","reason":"Blood in vomit needs immediate medical assistance.","all":[{"field":"vomit_blood","values":["Yes"]}],"source":"NHS vomiting blood","provenance":"assumed","status":"DRAFT"},{"id":"black_faint","urgency":"immediate","reason":"Black tar-like stool together with faintness or confusion needs immediate assistance.","all":[{"field":"black_stool","values":["Yes"]},{"field":"faint","values":["Yes"]}],"source":"NHS vomiting blood","provenance":"assumed","status":"DRAFT"},{"id":"collapse","urgency":"immediate","reason":"Fainting or new confusion needs immediate assessment.","all":[{"field":"faint","values":["Yes"]}],"source":"DRAFT conservative local adaptation","provenance":"assumed","status":"DRAFT"},{"id":"acute_pain","urgency":"immediate","reason":"Sudden severe abdominal pain needs immediate assessment.","all":[{"field":"severe_pain","values":["Yes"]}],"source":"NHS stomach ache","provenance":"assumed","status":"DRAFT"},{"id":"rigid_abdomen","urgency":"immediate","reason":"A hard and very painful abdomen needs immediate assessment.","all":[{"field":"rigid","values":["Yes"]}],"source":"DRAFT local adaptation","provenance":"assumed","status":"DRAFT"},{"id":"obstruction","urgency":"immediate","reason":"Abdominal swelling with vomiting and inability to pass stool/gas needs immediate assessment.","all":[{"field":"distended","values":["Yes"]},{"field":"vomiting","values":["Yes"]},{"field":"no_gas","values":["Yes"]}],"source":"DRAFT local adaptation","provenance":"assumed","status":"DRAFT"},{"id":"fluid_intolerance","urgency":"immediate","reason":"Inability to keep fluids down needs immediate assessment.","all":[{"field":"fluids","values":["Yes"]}],"source":"DRAFT local adaptation","provenance":"assumed","status":"DRAFT"},{"id":"biliary_fever","urgency":"immediate","reason":"Yellow eyes, fever/chills and upper-right pain need immediate assessment.","all":[{"field":"jaundice","values":["Yes"]},{"field":"fever","values":["Yes"]},{"field":"pain_site","values":["Right upper"]}],"source":"DRAFT local adaptation","provenance":"assumed","status":"DRAFT"},{"id":"saliva","urgency":"immediate","reason":"Inability to swallow saliva needs immediate assistance.","all":[{"field":"swallowing","values":["Cannot swallow saliva"]}],"source":"DRAFT local adaptation","provenance":"assumed","status":"DRAFT"},{"id":"melaena","urgency":"prompt","reason":"Black tar-like stools need prompt medical assessment.","all":[{"field":"black_stool","values":["Yes"]}],"source":"NHS rectal bleeding","provenance":"assumed","status":"DRAFT"},{"id":"black_colour","urgency":"prompt","reason":"Reported black sticky stool needs prompt medical assessment.","all":[{"field":"stool_colour","values":["Black and sticky"]}],"source":"NHS rectal bleeding","provenance":"assumed","status":"DRAFT"},{"id":"dysphagia","urgency":"prompt","reason":"Difficulty swallowing needs prompt specialist assessment.","all":[{"field":"swallowing","values":["Solids","Liquids","Both"]}],"source":"NICE NG12 1.2.1 (local adaptation)","provenance":"assumed","status":"DRAFT"},{"id":"jaundice","urgency":"prompt","reason":"Yellow eyes need prompt medical assessment.","all":[{"field":"jaundice","values":["Yes"]}],"source":"NICE NG12 (local adaptation)","provenance":"assumed","status":"DRAFT"},{"id":"loss","urgency":"prompt","reason":"Unintentional weight loss needs prompt clinical assessment.","all":[{"field":"weight_loss","values":["Yes"]}],"source":"NICE NG12 (local adaptation)","provenance":"assumed","status":"DRAFT"},{"id":"bleeding","urgency":"prompt","reason":"Rectal bleeding needs prompt clinical assessment.","all":[{"field":"rectal_blood","values":["Yes"]}],"source":"NICE NG12 (local adaptation)","provenance":"assumed","status":"DRAFT"},{"id":"persistent","urgency":"prompt","reason":"Persistent symptoms need prompt clinical review.","all":[{"field":"duration","values":["More than 6 weeks"]}],"source":"DRAFT local adaptation","provenance":"assumed","status":"DRAFT"}],"advice":{"review":"Arrange a clinician review. These answers cannot exclude serious disease. Seek immediate assistance if symptoms become severe or new warning signs appear.","prompt":"Seek prompt assessment by a doctor or hospital. Do not wait for this app's AI or online review if symptoms worsen.","immediate":"Seek immediate medical assistance or visit a hospital now. Tell clinic staff immediately if you are at the clinic. Do not wait for the AI assessment or online review."}}$content$);
